class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        if amount < 0:
            return -1
        elif amount == 0:
            return 0
        minCnt = float('inf')
        for coin in coins:
            cnt = self.coinChange(coins, amount - coin)
            if cnt == -1:
                continue
            minCnt = min(minCnt, cnt + 1)
        if minCnt == float('inf'):
            return -1
        else:
            return minCnt
